/// Equivalent to `HTMLStripCharFilter.zzUnpackcmap_blocks()`.
fn zz_unpackcmap_blocks() -> Box<[i32]> {
    let mut result = vec![0; 28928];
    let offset = 0;
    zz_unpackcmap_blocks_packed(&utf16(ZZ_CMAP_BLOCKS_PACKED_0), offset, &mut result);
    result.into_boxed_slice()
}

/// Equivalent to `HTMLStripCharFilter.zzUnpackcmap_blocks(String, int, int[])`.
fn zz_unpackcmap_blocks_packed(packed: &[u16], offset: usize, result: &mut [i32]) -> usize {
    let mut i = 0; /* index in packed string  */
    let mut j = offset; /* index in unpacked array */
    let l = packed.len();
    while i < l {
        let mut count = i32::from(packed[i]);
        i += 1;
        let value = i32::from(packed[i]);
        i += 1;
        loop {
            result[j] = value;
            j += 1;
            count -= 1;
            if count <= 0 {
                break;
            }
        }
    }
    j
}

