/// Equivalent to `HTMLStripCharFilter.zzUnpackAction()`.
fn zz_unpack_action() -> Box<[i32]> {
    let mut result = vec![0; 3465];
    let offset = 0;
    zz_unpack_action_packed(&utf16(ZZ_ACTION_PACKED_0), offset, &mut result);
    result.into_boxed_slice()
}

/// Equivalent to `HTMLStripCharFilter.zzUnpackAction(String, int, int[])`.
fn zz_unpack_action_packed(packed: &[u16], offset: usize, result: &mut [i32]) -> usize {
    let mut i = 0; /* index in packed string  */
    let mut j = offset; /* index in unpacked array */
    let l = packed.len();
    while i < l {
        let mut count = i32::from(packed[i]);
        i += 1;
        let value = i32::from(packed[i]);
        i += 1;
        loop {
            result[j] = value;
            j += 1;
            count -= 1;
            if count <= 0 {
                break;
            }
        }
    }
    j
}

