/// Equivalent to `HTMLStripCharFilter.zzUnpackRowMap()`.
fn zz_unpack_row_map() -> Box<[i32]> {
    let mut result = vec![0; 3465];
    let offset = 0;
    zz_unpack_row_map_packed(ZZ_ROWMAP_PACKED_0, offset, &mut result);
    result.into_boxed_slice()
}

/// Equivalent to `HTMLStripCharFilter.zzUnpackRowMap(String, int, int[])`.
fn zz_unpack_row_map_packed(packed: &[u16], offset: usize, result: &mut [i32]) -> usize {
    let mut i = 0; /* index in packed string  */
    let mut j = offset; /* index in unpacked array */
    let l = packed.len();
    while i < l {
        let high = i32::from(packed[i]) << 16;
        i += 1;
        result[j] = high | i32::from(packed[i]);
        i += 1;
        j += 1;
    }
    j
}

